'use strict'

const { ipcRenderer } = require( 'electron' )

let modalId = null


// Listen for the modal ID response from the main process
ipcRenderer.on( 'open-modal-response', ( event, id ) => {
	
	modalId = id
})


module.exports.openModal = function( url, width, height, resize ) {
	
	ipcRenderer.send( 'open-modal', { url, width, height, resize } )
}


module.exports.closeModal = function() {
	
	if( modalId !== null ) {
		
		ipcRenderer.send( 'close-modal-window', modalId )
		
	} else {
		
		ipcRenderer.send( 'close-current-window' )
	}
}
